<?php
if(PHP_SAPI!=='cli'||getenv('DB_NAME')!=='sukamulya_ui_test')exit(1);
$db=new mysqli('localhost','root','','sukamulya_ui_test');$c=json_decode(file_get_contents(__DIR__.'/../tmp/adminqa/sub-browser.json'),TRUE);
function owner_check($ok,$label){if(!$ok)throw new RuntimeException($label);echo 'PASS '.$label.PHP_EOL;}
class OwnerHttp{
 public $curl,$html,$code;function __construct(){$this->curl=curl_init();curl_setopt_array($this->curl,array(CURLOPT_RETURNTRANSFER=>TRUE,CURLOPT_COOKIEFILE=>'',CURLOPT_PROXY=>'',CURLOPT_TIMEOUT=>30));}
 function go($path,$data=NULL){if($data!==NULL){foreach(curl_getinfo($this->curl,CURLINFO_COOKIELIST) as $cookie){$p=explode("\t",$cookie);if(($p[5]??'')==='csrf_sukamulya_cookie')$data['csrf_sukamulya']=$p[6];}curl_setopt_array($this->curl,array(CURLOPT_POST=>TRUE,CURLOPT_POSTFIELDS=>http_build_query($data)));}else curl_setopt($this->curl,CURLOPT_HTTPGET,TRUE);curl_setopt($this->curl,CURLOPT_URL,'http://127.0.0.1:8097/'.$path);$this->html=curl_exec($this->curl);$this->code=curl_getinfo($this->curl,CURLINFO_HTTP_CODE);if(preg_match('/An uncaught Exception|Fatal error|A PHP Error|A Database Error|Severity:/',$this->html))throw new RuntimeException('Application error '.$path);return $this;}
 function login($name,$pw,$platform=FALSE){$path=$platform?'platform/login':'admin/login';$this->go($path);return $this->go($path,array('username'=>$name,'password'=>$pw));}
}
$a=(new OwnerHttp)->login($c['username'],$c['password']);$a->go('admin');owner_check($a->code===200&&strpos($a->html,'ad-topbar')!==FALSE&&strpos($a->html,'dbh-hero')!==FALSE&&strpos($a->html,'</html>')!==FALSE,'Admin dashboard renders complete header, sidebar and content');
$a->go('admin/akun');owner_check($a->code===200&&strpos($a->html,'value="super_admin"')===FALSE&&strpos($a->html,'<strong>'.$c['platform'].'</strong>')===FALSE,'Owner absent from account list and role selector');
$a->go('admin/akun',array('username'=>'fakeowner','full_name'=>'Fake Owner','role'=>'super_admin','password'=>$c['password'],'is_active'=>1));owner_check($a->code===403,'Cannot create Super Admin via account endpoint');
$a->go('admin/akun',array('username'=>$c['platform'],'role'=>'admin','password'=>$c['password'],'is_active'=>1));owner_check($a->code===200&&strpos($a->html,'Username tidak tersedia')!==FALSE,'Server owner username reserved outside pengurus accounts');
$a->go('admin/langganan?tab=fitur');owner_check(strpos($a->html,'class="sp-category-form"')===FALSE,'Ordinary administrator has no commercial controls');
foreach(array('admin/langganan/kelola','admin/langganan/paket','platform/langganan','platform/paket') as $path){$a->go($path);owner_check(in_array($a->code,array(302,303,307),TRUE),'Separate owner authentication required '.$path);}
$before=$db->query("SELECT commercial_type FROM subscription_catalog WHERE feature_code='social_aid'")->fetch_assoc();$a->go('admin/langganan/fitur',array('feature_code'=>'social_aid','commercial_type'=>'FREE'));$after=$db->query("SELECT commercial_type FROM subscription_catalog WHERE feature_code='social_aid'")->fetch_assoc();owner_check($before===$after,'Forged category request cannot change commercial access');
$legacy='legacy'.bin2hex(random_bytes(3));$hash=password_hash($c['password'],PASSWORD_DEFAULT);$s=$db->prepare('INSERT INTO platform_admins(username,password_hash,is_active)VALUES(?,?,1)');$s->bind_param('ss',$legacy,$hash);$s->execute();$legacy_id=$db->insert_id;
$bad=(new OwnerHttp)->login($legacy,$c['password'],TRUE);owner_check($bad->code===200&&strpos($bad->html,'Username atau password salah')!==FALSE,'Legacy database identity cannot authenticate as server owner');$db->query('DELETE FROM platform_admins WHERE id='.(int)$legacy_id);
$shared=(new OwnerHttp)->login($c['platform'],'incorrect-owner-password',FALSE);owner_check($shared->code===200&&strpos($shared->html,'Username atau password salah')!==FALSE,'Owner wrong password denied on ordinary login screen');
$shared->login($c['platform'],$c['password'],FALSE);owner_check(in_array($shared->code,array(302,303,307),TRUE),'Owner can enter through ordinary login screen');$shared->go('platform/paket');owner_check($shared->code===200,'Shared login routes to owner control');$shared->go('admin');owner_check(in_array($shared->code,array(302,303,307),TRUE),'Shared login never creates a pengurus identity');
$p=(new OwnerHttp)->login($c['platform'],$c['password'],TRUE);owner_check(in_array($p->code,array(302,303,307),TRUE),'Server-configured owner authenticates');$p->go('admin');owner_check(in_array($p->code,array(302,303,307),TRUE),'Owner login creates no pengurus session');
foreach(array('platform/langganan','platform/paket') as $path){$p->go($path);owner_check($p->code===200&&strpos($p->html,'</html>')!==FALSE,'Owner full control page '.$path);}
$p->go('platform/langganan',array('action'=>'catalog','feature_code'=>'social_aid','commercial_type'=>'PREMIUM'));owner_check(in_array($p->code,array(302,303,307),TRUE),'Owner controls Premium classification');$audit=$db->query("SELECT * FROM subscription_audit_logs WHERE action='catalog' ORDER BY id DESC LIMIT 1")->fetch_assoc();owner_check((int)$audit['actor_id']===0&&(json_decode($audit['after_json'],TRUE)['_actor_scope']??'')==='platform_owner','Owner audit is namespaced outside pengurus IDs');
$s=$db->prepare('SELECT COUNT(*) n FROM admins WHERE username=?');$s->bind_param('s',$c['platform']);$s->execute();owner_check((int)$s->get_result()->fetch_assoc()['n']===0,'No owner record stored in admins');
$config=file_get_contents(__DIR__.'/../tmp/adminqa/application/config/platform_owner.php');owner_check(strpos($config,$c['password'])===FALSE,'Owner password is not stored in plaintext');
$p->go('platform/paket',array('action'=>'presentation','subscription_basic_name'=>'Gratis (Basic)','subscription_page_title'=>'Paket & Langganan Saya','subscription_page_subtitle'=>'Kelola paket, masa aktif, dan akses fitur aplikasi RT/RW Anda.'));owner_check(in_array($p->code,array(302,303,307),TRUE),'Owner can edit presentation');
$p->go('platform/logout',array());$p->go('platform/paket');owner_check(in_array($p->code,array(302,303,307),TRUE),'Owner logout revokes platform access');
echo "Owner separation verified on disposable database only.\n";
